typedef enum {
    N_PROGRAM, N_FUNCDEF, N_FUNCCALL, N_VARDECL, N_ASSIGN, N_COPY,
    N_INC, N_DEC, N_PRINT, N_IF, N_WHILE, N_BREAK, N_CONTINUE,
