void tl_tokens_init(TlTokVec *v) { memset(v, 0, sizeof *v); }
void tl_tokens_free(TlTokVec *v) {
    for (int i = 0; i < v->count; i++) free(v->items[i].text);
    free(v->items); free(v->error);
    memset(v, 0, sizeof *v);
}

const char *tl_tokname(TlTokKind k) {
    switch (k) {
    case T_EOF: return "EOF"; case T_IDENT: return "Bezeichner";
    case T_NUMBER: return "Zahl"; case T_STRING: return "Zeichenkette";
    default: return "Keyword";
    }
}

static void push(TlTokVec *v, TlTokKind k, const char *t, int line) {
    if (v->count + 1 >= v->cap) {
        int nc = v->cap ? v->cap * 2 : 64;
        TlToken *ni = (TlToken*)realloc(v->items, (size_t)nc * sizeof *ni);
        if (!ni) return;
        v->items = ni; v->cap = nc;
    }
    TlToken *t2 = &v->items[v->count++];
    t2->kind = k; t2->line = line;
    t2->text = t ? (char*)malloc(strlen(t)+1) : NULL;
    if (t2->text) strcpy(t2->text, t);
}

