static int kw_match_at(const char *p, const char *kw) {
    size_t n = strlen(kw);
    if (strncmp(p, kw, n) != 0) return 0;
    /* Naechstes Zeichen darf kein Ident-Zeichen sein (ausser temporaere Namen sind exakt). */
    char c = p[n];
    if (c == '\0' || c == '\n' || c == '"' || c == ' ' || c == '\t' || c == '\r') return 1;
    return 0;
}

int tl_lex(const char *src, const char *filename, TlTokVec *out) {
    (void)filename;
    int line = 1;
    const char *p = src;
    while (*p) {
        if (*p == '\n') { push(out, T_NEWLINE, NULL, line); line++; p++; continue; }
        if (*p == ' ' || *p == '\t' || *p == '\r') { p++; continue; }
        if (*p == '#') { while (*p && *p != '\n') p++; continue; }
        if (*p == '/' && p[1] == '/') { while (*p && *p != '\n') p++; continue; }
        if (*p == '"') {
            p++;
            char buf[4096]; size_t bl = 0;
            while (*p && *p != '"' && *p != '\n' && bl + 1 < sizeof buf) {
                if (*p == '\\' && p[1]) { buf[bl++] = *p++; buf[bl++] = *p++; }
                else buf[bl++] = *p++;
            }
            buf[bl] = '\0';
            if (*p == '"') p++;
            push(out, T_STRING, buf, line);
            continue;
        }
        int matched = 0;
        /* TEMP-Namen sind kleinteilig: erst exakte Pruefung, dann Grossbuchstaben-Keywords. */
        for (size_t i = 0; i < sizeof KWS / sizeof KWS[0]; i++) {
            int is_lower = (KWS[i].kw[0] >= 'a' && KWS[i].kw[0] <= 'z');
            if (!is_lower) {
                /* Nur an Wortgrenzen pruefen: Zeilen muessen am Token beginnen (nach Spaces). */
            }
            if (kw_match_at(p, KWS[i].kw)) { push(out, KWS[i].kind, KWS[i].kw, line); p += strlen(KWS[i].kw); matched = 1; break; }
        }
        if (matched) continue;
        if (isalpha((unsigned char)*p) || *p == '_') {
            char buf[256]; size_t bl = 0;
            while ((isalnum((unsigned char)*p) || *p == '_') && bl + 1 < sizeof buf) buf[bl++] = *p++;
            buf[bl] = '\0';
            push(out, T_IDENT, buf, line);
            continue;
        }
        if (isdigit((unsigned char)*p) || (*p == '-' && isdigit((unsigned char)p[1]))) {
            char buf[64]; size_t bl = 0;
            if (*p == '-') buf[bl++] = *p++;
            while (isdigit((unsigned char)*p) && bl + 1 < sizeof buf) buf[bl++] = *p++;
            buf[bl] = '\0';
            push(out, T_NUMBER, buf, line);
            continue;
        }
        if (strchr("+-*/%<>=!&|()", *p)) {
            char buf[4] = {0};
            buf[0] = *p++;
            if ((buf[0]=='='||buf[0]=='!'||buf[0]=='<'||buf[0]=='>') && *p == '=') buf[1] = *p++;
            push(out, T_IDENT, buf, line);
            continue;
        }
        {
            char msg[128];
            snprintf(msg, sizeof msg, "Unbekanntes Zeichen '%c'", *p);
            out->error = (char*)malloc(strlen(msg)+1); strcpy(out->error, msg);
            out->error_line = line;
            return -1;
        }
    }
    push(out, T_EOF, NULL, line);
    return 0;
}
