int tl_codegen(TlNode *prog, FILE *out, char **err_out) {
    char *err = NULL;
    fprintf(out, "/* Generiert aus TraumaLang. Startup-Banner + 8s Delay sind verpflichtend. */\n");
    fprintf(out, "#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n");
    fprintf(out, "#include \"runtime.h\"\n\n");
    /* Vorab-Deklarationen: alle Variablen als long + String-Support via Zeiger ist bewusst einfach gehalten:
       jede Variable wird als long angelegt; String-Zuweisungen nutzen einen separaten const char*-Slot. */
    fprintf(out, "int main(void) {\n");
    fprintf(out, "    srand(1337);\n");
    fprintf(out, "    tl_startup_banner();\n");
    if (gen_body(prog->body, out, 1, &err)) { if (err_out) *err_out = err; return -1; }
    fprintf(out, "    return 0;\n}\n");
    return 0;
}
