{"content":"#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "explain.h"

static void ex_indent(FILE *o, int n) { for (int i = 0; i < n; i++) fputs("  ", o); }

/* Mueder SysAdmin, Montag 10:30 Uhr, auf Deutsch. Technische + satirische Bedeutung. */
static void ex_node(TlNode *s, FILE *o, int ind) {
    ex_indent(o, ind);
    switch (s->kind) {
    case N_VARDECL:
        if (!s->name) fprintf(o, "- THERE IS NO LEVEL I OR II (Zeile %d): statischer Marker ohne Namen. Technisch: naechste Deklaration wird statisch markiert. Satire: Es gibt weder Level I noch II, nur Hoffnung.\n", s->line);
        else fprintf(o, "- WE HAVE 240 EMPLOYEES ... %s (Zeile %d): Variable wird angelegt und lebt bis Prozessende. Technisch: TlVal-Deklaration. Satire: 240 Leute, 340 Accounts, keiner weiss, wem was gehoert.\n", s->name, s->line);
        break;
    case N_ASSIGN:
        fprintf(o, "- I NEED YOUR CLOTHES ... %s (Zeile %d): Zuweisung. Satire: Gib alles her, auch das Motorrad.\n", s->name ? s->name : "?", s->line); break;
    case N_COPY:
        fprintf(o, "- YOU ARE NOT YOU YOU ARE ME %s %s (Zeile %d): kopiert den Wert von %s nach %s.\n", s->name, s->name2, s->line, s->name2, s->name); break;
    case N_INC: fprintf(o, "- WE NEED TO SCALE %s (Zeile %d): erhoeht um 1. Mehr Leute, gleiche Arbeit.\n", s->name, s->line); break;
    case N_DEC: fprintf(o, "- WE NEED TO DOWNSIZE %s (Zeile %d): verringert um 1. Weniger Leute, gleiche Arbeit.\n", s->name, s->line); break;
    case N_PRINT:
        fprintf(o, "- Ausgabe (Zeile %d, Modus %d): gibt den Wert aus. Satire je nach Kanal: Slack, Cloud (+2s, +$0.30), Grafana (nur bei 50%% Glueck), Eskalation (+8s).\n", s->line, s->print_kind); break;
    case N_TODO_JIRA: fprintf(o, "- PUT IT IN JIRA %s (Zeile %d): wird als TODO-Kommentar abgelegt und nie wieder angefasst.\n", s->name ? s->name : "", s->line); break;
    case N_NULL_SINK: fprintf(o, "- KNOWLEDGE GOES IN DOESNT COME OUT (Zeile %d): Ausgabe nach /dev/null. Wissen geht rein, kommt nie raus.\n", s->line); break;
    case N_IF: fprintf(o, "- DO IT FOR THE METRICS (Zeile %d): if-Block. Was gemessen wird, wird verbessert. Oder auch nicht.\n", s->line); break;
    case N_WHILE: fprintf(o, "- STICK AROUND UNTIL THE SPRINT ENDS (Zeile %d): while-Schleife. Der Sprint endet nie.\n", s->line); break;
    case N_BREAK: fprintf(o, "- CONSIDER THAT A DIVORCE (Zeile %d): break. Endgueltig.\n", s->line); break;
    case N_CONTINUE: fprintf(o, "- LET'S CIRCLE BACK LATER (Zeile %d): continue. Wir reden spaeter drueber. Nie.\n", s->line); break;
    case N_FUNCDEF: fprintf(o, "- WE NEED TO TAKE THIS OFFLINE %s (Zeile %d): Funktionsdefinition. Wird offline geklaert, also nie.\n", s->name, s->line); break;
    case N_FUNCCALL: fprintf(o, "- Aufruf %s() (Zeile %d).\n", s->name, s->line); break;
    case N_COMMENT: fprintf(o, "- Satire-Marker: %s (Zeile %d). Technisch: Kommentar, keine Wirkung.\n", s->sval, s->line); break;
    case N_METRICS_INC: fprintf(o, "- THINGS THAT GET MEASURED GET IMPROVED (Zeile %d): Metrics-Zaehler +1.\n", s->line); break;
    case N_METRICS_LOOP: fprintf(o, "- Endlose Metrics-Schleife (Zeile %d): Vorsicht, terminiert nicht. So wie das Reporting.\n", s->line); break;
    case N_CHAOS: fprintf(o, "- Chaos-Operation (Zeile %d): kontrollierter Zufall, kein echter Schaden.\n", s->line); break;
    case N_SLEEP_OP: fprintf(o, "- WE NEED TO SYNC (Zeile %d): wartet 8 Sekunden. Governance braucht Zeit.\n", s->line); break;
    case N_DOUBLE_RUN: fprintf(o, "- DOUBLE-BOOKED (Zeile %d): Funktion %s wird 2x sequenziell ausgefuehrt. Multithreading fuer den Kalender.\n", s->line, s->name ? s->name : "(keine)"); break;
    case N_RESET: fprintf(o, "- HAVE YOU TRIED TURNING IT OFF AND ON AGAIN (Zeile %d): Reset-Strategie, siehe Doku.\n", s->line); break;
    case N_DIRECTIVE: fprintf(o, "- Direktive %s (Zeile %d).\n", s->sval ? s->sval : "?", s->line); break;
    default: fprintf(o, "- Konstrukt (Zeile %d).\n", s->line); break;
    }
}

static void ex_list(TlNodeList *l, FILE *o, int ind) {
    for (; l; l = l->next) {
        ex_node(l->node, o, ind);
        if (l->node->kind == N_FUNCDEF || l->node->kind == N_IF || l->node->kind == N_WHILE) {
            ex_list(l->node->body, o, ind + 1);
            ex_list(l->node->else_body, o, ind + 1);
        }
    }
}

int tl_explain(TlNode *prog, FILE *out) {
    fprintf(out, "Moin. Montag, 10:30 Uhr, Kaffee Nummer drei. Hier die Akte:\n\n");
    fprintf(out, "Jedes TraumaLang-Programm startet mit LOADING DEPENDENCIES... und wartet 8 Sekunden. Warum? Weil es kann.\n\n");
    ex_list(prog->body, out, 0);
    fprintf(out, "\nFazit: Irgendwas davon ist bestimmt DNS. Feierabend.\n");
    return 0;
}
