{"content":"#include <assert.h>
#include <stdio.h>
#include <string.h>
#include "../src/lexer.h"

/* Lexer-Tests: Mehrwort-Keywords, Strings, Zahlen, Zeilennummern. Nur schreiben, nicht ausfuehren. */
static int t_multiword(void) {
    TlTokVec v; tl_tokens_init(&v);
    int rc = tl_lex("IT'S SHOWTIME\nYOU HAVE BEEN TERMINATED\n", "t", &v);
    assert(rc == 0 && v.items[0].kind == T_SHOWTIME && v.items[2].kind == T_TERMINATED);
    tl_tokens_free(&v); return 0;
}
static int t_enterprise(void) {
    TlTokVec v; tl_tokens_init(&v);
    int rc = tl_lex("WE HAVE 240 EMPLOYEES AND 340 ACTIVE ACCOUNTS x\n", "t", &v);
    assert(rc == 0 && v.items[0].kind == T_VAR_ENTERPRISE && v.items[1].kind == T_IDENT);
    tl_tokens_free(&v); return 0;
}
static int t_string(void) {
    TlTokVec v; tl_tokens_init(&v);
    int rc = tl_lex("TALK TO THE HAND \"Hi \\\"Welt\\\"\"\n", "t", &v);
    assert(rc == 0 && v.items[1].kind == T_STRING);
    tl_tokens_free(&v); return 0;
}
static int t_line(void) {
    TlTokVec v; tl_tokens_init(&v);
    int rc = tl_lex("TALK TO THE HAND x\n@" , "t", &v);
    assert(rc != 0 && v.error_line == 2);
    tl_tokens_free(&v); return 0;
}
int main(void) { t_multiword(); t_enterprise(); t_string(); t_line(); printf("lexer ok\n"); return 0; }
","path":"tests/lexer_tests.c"}

{"content":"#include <assert.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include "../src/lexer.h"
#include "../src/parser.h"
#include "../src/ast.h"

static TlNode *parse_src(const char *src) {
    TlTokVec v; tl_tokens_init(&v);
    if (tl_lex(src, "t", &v)) { tl_tokens_free(&v); return NULL; }
    char *err = NULL; int el = 0;
    TlNode *p = tl_parse(&v, &err, &el);
    free(err); tl_tokens_free(&v);
    return p;
}

/* Parser/AST: Programmgeruest, Variablen, if/else, while+break/continue, Funktionen, Fehler mit Zeile. */
int main(void) {
    TlNode *p = parse_src("IT'S SHOWTIME\nYOU HAVE BEEN TERMINATED\n");
    assert(p && p->kind == N_PROGRAM); tl_node_free(p);

    p = parse_src("IT'S SHOWTIME\nWE HAVE 240 EMPLOYEES AND 340 ACTIVE ACCOUNTS x\nYOU HAVE BEEN TERMINATED\n");
    assert(p); tl_node_free(p);

    p = parse_src("IT'S SHOWTIME\nDO IT FOR THE METRICS x\nTALK TO THE HAND \"a\"\nBLUE IS BROKEN GREEN IS WORSE\nTALK TO THE HAND \"b\"\nYOU HAVE BEEN TERMINATED\nYOU HAVE BEEN TERMINATED\n");
    assert(p); tl_node_free(p);

    p = parse_src("IT'S SHOWTIME\nSTICK AROUND UNTIL THE SPRINT ENDS x\nCONSIDER THAT A DIVORCE\nLET'S CIRCLE BACK LATER\nYOU HAVE BEEN TERMINATED\nYOU HAVE BEEN TERMINATED\n");
    assert(p); tl_node_free(p);

    p = parse_src("IT'S SHOWTIME\nWE NEED TO TAKE THIS OFFLINE f\nTALK TO THE HAND \"x\"\nTHIS COULD HAVE BEEN AN EMAIL\nYOU HAVE BEEN TERMINATED\n");
    assert(p); tl_node_free(p);

    /* Fehlerfaelle: fehlendes TERMINATED, falscher Blockabschluss */
    p = parse_src("IT'S SHOWTIME\nTALK TO THE HAND \"x\"\n");
    assert(!p);
    p = parse_src("TALK TO THE HAND \"x\"\nYOU HAVE BEEN TERMINATED\n");
    assert(!p);

    printf("parser ok\n"); return 0;
}
","path":"tests/parser_tests.c"}

{"content":"#include <assert.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include "../src/lexer.h"
#include "../src/parser.h"
#include "../src/ast.h"
#include "../src/codegen.h"

/* Codegen-Tests: Startup-Banner, TlVal-Deklaration, String-Escaping, if/while-Verschachtelung. */
static char *gen(const char *src) {
    TlTokVec v; tl_tokens_init(&v);
    if (tl_lex(src, "t", &v)) return NULL;
    char *err = NULL; int el = 0;
    TlNode *p = tl_parse(&v, &err, &el);
    free(err);
    if (!p) { tl_tokens_free(&v); return NULL; }
    FILE *f = fopen("tests/_out.c", "w");
    char *cerr = NULL;
    int rc = tl_codegen(p, f, &cerr);
    fclose(f);
    tl_node_free(p); tl_tokens_free(&v);
    if (rc) return NULL;
    FILE *r = fopen("tests/_out.c", "r");
    static char buf[65536];
    size_t n = fread(buf, 1, sizeof buf - 1, r);
    fclose(r); buf[n] = '\0';
    return buf;
}

int main(void) {
    char *c = gen("IT'S SHOWTIME\nWE HAVE 240 EMPLOYEES AND 340 ACTIVE ACCOUNTS x\nI NEED YOUR CLOTHES YOUR BOOTS AND YOUR MOTORCYCLE x \"A \\\"B\\\"\"\nYOU HAVE BEEN TERMINATED\n");
    assert(c && strstr(c, "tl_startup_banner") && strstr(c, "TlVal x") && strstr(c, "A \\\"B\\\""));
    c = gen("IT'S SHOWTIME\nSTICK AROUND UNTIL THE SPRINT ENDS x\nTALK TO THE HAND \"s\"\nYOU HAVE BEEN TERMINATED\nYOU HAVE BEEN TERMINATED\n");
    assert(c && strstr(c, "while"));
    printf("codegen ok\n"); return 0;
}
","path":"tests/codegen_tests.c"}

{"content":"#include <assert.h>
#include <stdio.h>
#include <string.h>
#include "../src/rewrite.h"

/* Rewrite-Tests: alle acht Sprachen erzeugen gueltigen Rahmen; Roast fuegt Marker hinzu. */
static int has(const char *path, const char *needle) {
    FILE *f = fopen(path, "r");
    static char buf[65536];
    size_t n = f ? fread(buf, 1, sizeof buf - 1, f) : 0;
    if (f) fclose(f);
    buf[n] = '\0';
    return strstr(buf, needle) != NULL;
}

static void write_in(const char *content) {
    FILE *f = fopen("tests/_in.txt", "w");
    fputs(content, f); fclose(f);
}

int main(void) {
    char *w = NULL;
    write_in("fn main() {\nlet x = 1;\nprintln!(\"hi\");\n}\n");
    assert(tl_rewrite_file("rust", "tests/_in.txt", "tests/_o.tl", 0, &w) == 0);
    assert(has("tests/_o.tl", "IT'S SHOWTIME"));

    write_in("package m\nfunc main() {\nfmt.Println(\"hi\")\n}\n");
    assert(tl_rewrite_file("go", "tests/_in.txt", "tests/_o.tl", 0, &w) == 0);
    assert(has("tests/_o.tl", "WE NEED TO SYNC"));

    write_in("def f():\n    print(\"hi\")\n");
    assert(tl_rewrite_file("python", "tests/_in.txt", "tests/_o.tl", 0, &w) == 0);

    write_in("async function f() {}\nconsole.log(\"hi\");\n");
    assert(tl_rewrite_file("javascript", "tests/_in.txt", "tests/_o.tl", 0, &w) == 0);
    assert(has("tests/_o.tl", "DOUBLE-BOOKED"));

    write_in("async function f() {}\nconsole.log(\"hi\");\n");
    assert(tl_rewrite_file("typescript", "tests/_in.txt", "tests/_o.tl", 0, &w) == 0);

    write_in("class A { public static void main(String[] a) { System.out.println(\"hi\"); } }\n");
    assert(tl_rewrite_file("java", "tests/_in.txt", "tests/_o.tl", 0, &w) == 0);

    write_in("int main() { printf(\"hi\"); }\n");
    assert(tl_rewrite_file("c", "tests/_in.txt", "tests/_o.tl", 0, &w) == 0);
    assert(tl_rewrite_file("cpp", "tests/_in.txt", "tests/_o.tl", 1, &w) == 0);
    assert(has("tests/_o.tl", "BLOCKED BY ANOTHER TEAM"));

    printf("rewrite ok\n"); return 0;
}
","path":"tests/rewrite_tests.c"}

