    for (l = prog->body; l; l = l->next) {
        if (l->node->kind == N_FUNCDEF) continue;
        if (gen_stmt(l->node, out, 1, &err)) { if (err_out) *err_out = err; return -1; }
    }
    if (body_has_func(prog->body, "main")) fprintf(out, "    tlf_main();\n");
    fprintf(out, "    return 0;\n}\n");
    return 0;
}"}

